function buildCommand() {
  const __args = [['leaderboard'], 'Economy', 'Show the richest users', async ({ sock, from, msg, db }) => {
  const all = Object.entries(db.get().economy).map(([n, e]) => ({ n, total: e.balance + e.bank })).sort((a, b) => b.total - a.total).slice(0, 10);
  if (!all.length) return sock.sendMessage(from, { text: 'No economy data yet.' }, { quoted: msg });
  await sock.sendMessage(from, { text: `🏆 *Leaderboard*\n\n${all.map((e, i) => `${i + 1}. ${e.n} — ${e.total}`).join('\n')}` }, { quoted: msg });
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
